27	
28	// dupFixEscE 是 é（U+00E9）的 JSON 转义写法；dupFixEscA 是 a（U+0061）的
29	// JSON 转义写法。用反引号字符串拼接，保证配置原文里出现的就是 \uXXXX
30	// 序列，而不是解码后的字符本身。
31	const (
32		dupFixEscE = `\u` + `00E9`
33		dupFixEscA = `\u` + `0061`
34	)
35	
36	// dupFixFirstFlagText 拼出始终合法的第一份定义：启用、default=false、一条
37	// eq 规则 r1（plan 等于 "pro" 时返回 true）。keyJSON 是 key 的 JSON 字符串
38	// 内容（不含引号），可写直接字符或合法 Unicode 转义。
39	func dupFixFirstFlagText(keyJSON string) string {
40		return `{"key":"` + keyJSON + `","enabled":true,"default":false,"rules":[` +
41			`{"id":"r1","value":true,"conditions":[` +
42			`{"attribute":"plan","op":"eq","value":"pro"}]}]}`
43	}
44	
45	// dupFixSecondFlagText 拼出后一个开关：
46	//   - keyJSON：key 的 JSON 字符串内容，与第一份解码后同名，或改成新名字；
47	//   - enabledJSON：enabled 的布尔原文（"true"/"false"）；
48	//   - defaultJSON：""/"false"/"true"，空串表示省略 default 字段；
49	//   - listJSON：r2 规则唯一 in 条件的比较列表原文；
50	//   - reordered：为 true 时把开关、规则、条件对象内部的字段按另一种顺序书写，
51	//     报错阶段与位置不应受影响。
52	//
53	// r2 在 region 属于列表时返回 false，与第一份的 r1（返回 true）明确区分。
54	func dupFixSecondFlagText(keyJSON, enabledJSON, defaultJSON, listJSON string, reordered bool) string {
55		cond := `{"attribute":"region","op":"in","value":` + listJSON + `}`
56		rule := `{"id":"r2","value":false,"conditions":[` + cond + `]}`
57		if reordered {
58			cond = `{"value":` + listJSON + `,"op":"in","attribute":"region"}`
59			rule = `{"conditions":[` + cond + `],"value":false,"id":"r2"}`
60			s := `{"rules":[` + rule + `],"enabled":` + enabledJSON + `,"key":"` + keyJSON + `"`
61			if defaultJSON != "" {
62				s += `,"default":` + defaultJSON
63			}
64			return s + `}`
65		}
66		s := `{"key":"` + keyJSON + `","enabled":` + enabledJSON + `,`
67		if defaultJSON != "" {
68			s += `"default":` + defaultJSON + `,`
69		}
70		return s + `"rules":[` + rule + `]}`
71	}
72	
73	// dupFixConfigText 把两份开关组成一份 flags 数组文档；padded 时在文档前后
74	// 加入 JSON 允许的空白，报错与接受结果都不应改变。
75	func dupFixConfigText(first, second string, padded bool) string {
76		doc := `{"flags":[` + first + `,` + second + `]}`
77		if padded {
78			return " \t\r\n" + doc + "\n  \t"
79		}
80		return doc
81	}
82	
83	// dupFixAssertError 要求 ParseConfig 失败，且错误信息包含全部 wantSub、
84	// 不包含任何 notSub（用于锁定“当前只报这一处”，不提前暴露后续阶段问题）。
85	func dupFixAssertError(t *testing.T, label string, raw string, wantSub, notSub []string) {
86		t.Helper()
87		_, err := ParseConfig([]byte(raw))
88		if err == nil {
89			t.Fatalf("%s: expected config error, config=%s", label, raw)
90		}
91		msg := err.Error()
92		for _, want := range wantSub {
93			if !strings.Contains(msg, want) {
94				t.Fatalf("%s: error=%q, want substring %q\nconfig: %s", label, msg, want, raw)
95			}
96		}
97		for _, not := range notSub {
98			if strings.Contains(msg, not) {
99				t.Fatalf("%s: error=%q, must not contain %q\nconfig: %s", label, msg, not, raw)
100			}
101		}
102	}
103	
104	// TestDuplicateFlagKeyFixSequenceErrorStages 沿用户逐处修正的前三个阶段，
105	// 锁定报错的推进次序与精确定位；key 写法（直接字符 / 合法 Unicode 转义）、
106	// 对象内部字段顺序、文档空白各自组合后，三个阶段的报错都不变。
107	func TestDuplicateFlagKeyFixSequenceErrorStages(t *testing.T) {
108		spellings := []struct {
109			name string
110			json string
111		}{
112			{"direct", "café"},
113			{"escaped", "caf" + dupFixEscE},
114		}
115		stages := []struct {
116			name    string
117			defJSON string
118			list    string
119			wantSub []string
120			notSub  []string
121		}{
122			{
123				name:    "missing default reported first",
124				defJSON: "",
125				list:    `["eu",5]`,
126				wantSub: []string{`config.flags[1].default`, "field is required"},
127				notSub:  []string{"must be a string", "duplicate flag key"},
128			},
129			{
130				name:    "in-list member type error after default is fixed",
131				defJSON: "false",
132				list:    `["eu",5]`,
133				wantSub: []string{
134					`config.flags[1].rules[0].conditions[0].value[1]`,
135					"must be a string",
136				},
137				notSub: []string{"field is required", "duplicate flag key"},
138			},
139			{
140				name:    "duplicate key reported only after the flag is otherwise valid",
141				defJSON: "false",
142				list:    `["eu","cn"]`,
143				wantSub: []string{
144					`config.flags[1].key`,
145					"duplicate flag key",
146					`"café"`,
147					"first at flags[0]",
148				},
149				notSub: []string{"must be a string", "field is required"},
150			},
151		}
152		for _, sp := range spellings {
153			for _, reordered := range []bool{false, true} {
154				for _, padded := range []bool{false, true} {
155					for _, st := range stages {
156						label := "key=" + sp.name + "/reordered=" +
157							boolLabel(reordered) + "/padded=" + boolLabel(padded) + "/" + st.name
158						raw := dupFixConfigText(
159							dupFixFirstFlagText("café"),
160							dupFixSecondFlagText(sp.json, "true", st.defJSON, st.list, reordered),
161							padded)
162						dupFixAssertError(t, label, raw, st.wantSub, st.notSub)
163					}
164				}
165			}
166		}
167	}
168	
169	// TestDuplicateFlagKeyFixSequenceFirstFlagEscaped 覆盖反向拼写：第一份定义
170	// 用合法 Unicode 转义书写、后一份用直接字符。三个阶段的报错与解码后同名
171	// 的直接写法逐字一致，重复错误始终指向 flags[1] 并以 flags[0] 为第一次
172	// 出现的参照。
173	func TestDuplicateFlagKeyFixSequenceFirstFlagEscaped(t *testing.T) {
174		first := dupFixFirstFlagText("caf" + dupFixEscE)
175		cases := []struct {
176			name    string
177			defJSON string
178			list    string
179			wantSub []string
180			notSub  []string
181		}{
182			{"stage1 missing default", "", `["eu",5]`,
183				[]string{`config.flags[1].default`, "field is required"},
184				[]string{"must be a string", "duplicate flag key"}},
185			{"stage2 bad list member", "false", `["eu",5]`,
186				[]string{`config.flags[1].rules[0].conditions[0].value[1]`, "must be a string"},
187				[]string{"field is required", "duplicate flag key"}},
188			{"stage3 duplicate key", "false", `["eu","cn"]`,
189				[]string{`config.flags[1].key`, "duplicate flag key", `"café"`, "first at flags[0]"},
190				[]string{"must be a string", "field is required"}},
191		}
192		for _, tc := range cases {
193			t.Run(tc.name, func(t *testing.T) {
194				raw := dupFixConfigText(first,
195					dupFixSecondFlagText("café", "true", tc.defJSON, tc.list, false), false)
196				dupFixAssertError(t, tc.name, raw, tc.wantSub, tc.notSub)
197			})
198		}
199	
200		// 改名后两份共同接受；用解码后的名字找到的是第一份（转义书写的）定义，
201		// plan=pro 命中它的 r1。
202		raw := dupFixConfigText(first,
203			dupFixSecondFlagText("beta", "true", "true", `["eu","cn"]`, false), false)
204		cfg := mustParseConfig(t, raw)
205		if got := len(cfg.Flags); got != 2 {
206			t.Fatalf("both definitions must be kept, got %d flags", got)
207		}
208		flag := cfg.Find("café")
209		if flag != &cfg.Flags[0] {
210			t.Fatalf("decoded name must resolve to the first (escaped) definition")
211		}
212		if r := flag.Evaluate(mustParseContext(t, `{"plan":"pro"}`)); r.Value != true ||
213			r.Reason != EvalRule || r.RuleID == nil || *r.RuleID != "r1" {
214			t.Fatalf("first definition must stay in charge: %+v", r)
215		}
216	}
217	
218	// TestDuplicateFlagKeyFixSequenceRenamingAcceptsBothDefinitions 锁定第四阶段：
219	// 后一个开关改成不同名字后，两份定义都被接受——开关顺序不变；原开关键仍
220	// 解析到第一份定义（第一份 default=false、只有 r1；第二份 default=true、
221	// 只有 r2，二者不可互相覆盖）；新名字按第二份定义求值；任何一份都不能被
222	// 悄悄丢弃。写法、字段顺序与空白变体下接受结果一致。
223	func TestDuplicateFlagKeyFixSequenceRenamingAcceptsBothDefinitions(t *testing.T) {
224		renamedSpellings := []struct {
225			name string
226			json string
227		}{
228			{"direct", "beta"},
229			{"escaped", "bet" + dupFixEscA},
230		}
231		var canonical *Config
232		for _, sp := range renamedSpellings {
233			for _, reordered := range []bool{false, true} {
234				for _, padded := range []bool{false, true} {
235					label := "key=" + sp.name + "/reordered=" + boolLabel(reordered) +
236						"/padded=" + boolLabel(padded)
237					raw := dupFixConfigText(
238						dupFixFirstFlagText("café"),
239						dupFixSecondFlagText(sp.json, "true", "true", `["eu","cn"]`, reordered),
240						padded)
241					cfg := mustParseConfig(t, raw)
242					if len(cfg.Flags) != 2 {
243						t.Fatalf("%s: both definitions must be kept, got %d", label, len(cfg.Flags))
244					}
245					if cfg.Flags[0].Key != "café" || cfg.Flags[1].Key != "beta" {
246						t.Fatalf("%s: flag order/keys changed: %q, %q", label, cfg.Flags[0].Key, cfg.Flags[1].Key)
247					}
248					if sp.name == "direct" && !reordered && !padded {
249						canonical = cfg
250					}
251				}
252			}
253		}
254	
255		// 详细身份与求值断言只在标准写法上做一次。
256		first := &canonical.Flags[0]
257		second := &canonical.Flags[1]
258		if canonical.Find("café") != first || canonical.Find("beta") != second {
259			t.Fatal("Find must not be shadowed by the later definition, and both flags stay reachable")
260		}
261		if !first.Enabled || first.Default != false || len(first.Rules) != 1 ||
262			first.Rules[0].ID != "r1" || first.Rules[0].Value != true {
263			t.Fatalf("first definition altered: %+v", first)
264		}
265		if !second.Enabled || second.Default != true || len(second.Rules) != 1 ||
266			second.Rules[0].ID != "r2" || second.Rules[0].Value != false {
267			t.Fatalf("second definition altered: %+v", second)
268		}
269	
270		// plan=pro：第一份的 r1 命中并返回 true；第二份根本不引用 plan，
271		// 不可能给出这个结果——证明原开关键没有被后一次定义覆盖。
272		planPro := mustParseContext(t, `{"plan":"pro"}`)
273		r := first.Evaluate(planPro)
274		if r.Key != "café" || r.Value != true || r.Reason != EvalRule ||
275			r.RuleID == nil || *r.RuleID != "r1" {
276			t.Fatalf("café must evaluate by the first definition's r1: %+v", r)
277		}
278		// 解释模式走同一条定案路径，记录的也只是第一份的 r1。
279		ex := first.EvaluateExplain(planPro)
280		if ex.Value != true || ex.Reason != EvalRule || ex.RuleID == nil || *ex.RuleID != "r1" {
281			t.Fatalf("explain must also use the first definition: %+v", ex.EvalResult)
282		}
283		if len(ex.Explanation.Rules) != 1 || ex.Explanation.Rules[0].RuleID != "r1" ||
284			!ex.Explanation.Rules[0].Match {
285			t.Fatalf("explanation must record the first definition's r1: %+v", ex.Explanation)
286		}
287	
288		// 空上下文是两份 default 的直接对照：第一份 default=false；若第二份
289		// 覆盖了同名开关，这里会错误地得到 true。
290		empty := mustParseContext(t, `{}`)
291		if r := first.Evaluate(empty); r.Value != false || r.Reason != EvalDefault || r.RuleID != nil {
292			t.Fatalf("café must use the first default=false: %+v", r)
293		}
294		// 第二份在空上下文使用自己的 default=true。
295		if r := second.Evaluate(empty); r.Value != true || r.Reason != EvalDefault || r.RuleID != nil {
296			t.Fatalf("beta must use its own default=true: %+v", r)
297		}
298	
299		// region=eu：第二份的 r2 命中并返回 false；第一份不引用 region，只能
300		// 落回 default=false。两个名字在同一份配置里各自给出属于自己定义的结果。
301		regionEU := mustParseContext(t, `{"region":"eu"}`)
302		if r := second.Evaluate(regionEU); r.Key != "beta" || r.Value != false ||
303			r.Reason != EvalRule || r.RuleID == nil || *r.RuleID != "r2" {
304			t.Fatalf("beta must evaluate by the second definition's r2: %+v", r)
305		}
306		if r := first.Evaluate(regionEU); r.Value != false || r.Reason != EvalDefault {
307			t.Fatalf("café must not react to region: %+v", r)
308		}
309	}
310	
311	// TestDuplicateFlagKeyFixSequenceDisabledLaterFlag 锁定：后一个开关即使
312	// enabled=false（不会被求值、关闭固定 false），也必须经过与启用时完全相同
313	// 的完整校验——三个阶段的报错位置与原因不变；改名后它与第一份共同被接受，
314	// 且关闭开关的求值固定为 disabled。
315	func TestDuplicateFlagKeyFixSequenceDisabledLaterFlag(t *testing.T) {
316		first := dupFixFirstFlagText("café")
317		cases := []struct {
318			name    string
319			defJSON string
320			list    string
321			wantSub []string
322			notSub  []string
323		}{
324			{"stage1 missing default", "", `["eu",5]`,
325				[]string{`config.flags[1].default`, "field is required"},
326				[]string{"must be a string", "duplicate flag key"}},
327			{"stage2 bad list member", "false", `["eu",5]`,
328				[]string{`config.flags[1].rules[0].conditions[0].value[1]`, "must be a string"},
329				[]string{"field is required", "duplicate flag key"}},
330			{"stage3 duplicate key", "false", `["eu","cn"]`,
331				[]string{`config.flags[1].key`, "duplicate flag key", `"café"`, "first at flags[0]"},
332				[]string{"must be a string", "field is required"}},
333		}
334		for _, tc := range cases {
335			t.Run(tc.name, func(t *testing.T) {
336				raw := dupFixConfigText(first,
337					dupFixSecondFlagText("café", "false", tc.defJSON, tc.list, false), false)
338				dupFixAssertError(t, tc.name, raw, tc.wantSub, tc.notSub)
339			})
340		}
341	
342		// 改名后两份共同接受；第二个开关关闭，求值固定 disabled；原开关键仍是
343		// 第一份启用的定义。
344		raw := dupFixConfigText(first,
345			dupFixSecondFlagText("beta", "false", "true", `["eu","cn"]`, false), false)
346		cfg := mustParseConfig(t, raw)
347		ctx := mustParseContext(t, `{"plan":"pro","region":"eu"}`)
348		if r := cfg.Find("beta").Evaluate(ctx); r.Value != false || r.Reason != EvalDisabled || r.RuleID != nil {
349			t.Fatalf("renamed disabled flag must stay fixed false: %+v", r)
350		}
351		if r := cfg.Find("café").Evaluate(ctx); r.Value != true ||
352			r.Reason != EvalRule || r.RuleID == nil || *r.RuleID != "r1" {
353			t.Fatalf("original key must still use the first enabled definition: %+v", r)
354		}
355	}
356	
357	// boolLabel 给表驱动用例的布尔变体一个稳定的短标签。
358	func boolLabel(b bool) string {
359		if b {
360			return "true"
361		}
362		return "false"
363	}
364

